/* QueryID : com.demo.proworks.wbs.selectListWbsAll */ WITH RECURSIVE task_hierarchy AS ( SELECT t.task_id, t.task_name, t.task_des, t.task_status, t.is_test, t.is_design, t.task_depth, t.pt_task_id, t.task_st, t.task_et, t.task_rst, t.task_ret, t.task_asi, t.task_rate, t.pjt_id, t.user_id, pt.task_name as pt_task_name, CAST(t.task_id AS CHAR(1000)) AS sort_path FROM project_task t LEFT JOIN project_task pt ON t.pt_task_id = pt.task_id WHERE t.pjt_id = #{pjtId} AND (t.pt_task_id IS NULL OR t.pt_task_id = '')
UNION ALL
SELECT t.task_id, t.task_name, t.task_des, t.task_status, t.is_test, t.is_design, t.task_depth, t.pt_task_id, t.task_st, t.task_et, t.task_rst, t.task_ret, t.task_asi, t.task_rate, t.pjt_id, t.user_id, pt.task_name as pt_task_name, CONCAT(th.sort_path, '-', t.task_id) AS sort_path FROM project_task t INNER JOIN task_hierarchy th ON t.pt_task_id = th.task_id LEFT JOIN project_task pt ON t.pt_task_id = pt.task_id WHERE t.pjt_id = #{pjtId} ), ranked_tasks AS ( SELECT *, ROW_NUMBER() OVER (ORDER BY sort_path) as rn FROM task_hierarchy ) SELECT task_id as taskId, task_name as taskName, task_des as taskDes, task_status as taskStatus, is_test as isTest, is_design as isDesign, task_depth as taskDepth, pt_task_id as ptTaskId, pt_task_name as ptTaskName, task_st as taskSt, task_et as taskEt, task_rst as taskRst, task_ret as taskRet, task_asi as taskAsi, task_rate as taskRate, pjt_id as pjtId, user_id as userId FROM ranked_tasks WHERE rn BETWEEN ((#{pageIndex} - 1) * #{pageSize} + 1) AND (#{pageIndex} * #{pageSize}) ORDER BY sort_path

/* QueryID : com.demo.proworks.wbs.selectListCountWbsAll */ WITH RECURSIVE task_hierarchy AS ( SELECT task_id, pt_task_id FROM project_task WHERE pjt_id = #{pjtId} AND (pt_task_id IS NULL OR pt_task_id = '')
UNION ALL
SELECT t.task_id, t.pt_task_id FROM project_task t INNER JOIN task_hierarchy th ON t.pt_task_id = th.task_id WHERE t.pjt_id = #{pjtId} ) SELECT COUNT(*) as totcnt FROM task_hierarchy

/* QueryID : com.demo.proworks.wbs.selectListCountWbsSearch */ WITH RECURSIVE search_matches AS ( SELECT task_id, pt_task_id FROM project_task WHERE pjt_id = #{pjtId}
AND task_id like CONCAT('%', #{scTaskId}, '%')
AND task_name like CONCAT('%', #{scTaskName}, '%')
AND task_status like CONCAT('%', #{scTaskStatus}, '%')
AND task_asi like CONCAT('%', #{scTaskAsi}, '%')
AND task_rate like CONCAT('%', #{scTaskRate}, '%')
), parent_tasks AS ( SELECT task_id, pt_task_id FROM search_matches UNION ALL SELECT t.task_id, t.pt_task_id FROM project_task t INNER JOIN parent_tasks pt ON t.task_id = pt.pt_task_id WHERE t.pjt_id = #{pjtId} ), child_tasks AS ( SELECT task_id, pt_task_id FROM search_matches UNION ALL SELECT t.task_id, t.pt_task_id FROM project_task t INNER JOIN child_tasks ct ON t.pt_task_id = ct.task_id WHERE t.pjt_id = #{pjtId} ), all_related_tasks AS ( SELECT DISTINCT * FROM parent_tasks UNION SELECT DISTINCT * FROM child_tasks ) SELECT COUNT(*) as totcnt FROM all_related_tasks

